import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

fused_expert_cpp_source = """
#include <hip/hip_runtime.h>

template <typename T>
__device__ __forceinline__ T silu(T x) {
    return x * (1.0f / (1.0f + expf(-x)));
}

__global__ void fused_expert_mlp_kernel(
    const float* gate_weights,    // (n_experts, intermediate_size, hidden_size)
    const float* up_weights,       // (n_experts, intermediate_size, hidden_size)
    const float* down_weights,     // (n_experts, hidden_size, intermediate_size)
    const float* expanded_tokens,  // (num_tokens * top_k, hidden_size)
    const int32_t* topk_idx_flat,  // (num_tokens * top_k,)
    const float* topk_weights,     // (num_tokens, top_k)
    float* output,                 // (num_tokens, hidden_size)
    int num_tokens_original,
    int top_k,
    int hidden_size,
    int intermediate_size,
    int n_experts
) {
    extern __shared__ float shared_mem[];

    // Partition shared memory
    float* shared_gate = shared_mem;                           // size: intermediate_size * hidden_size
    float* shared_up = shared_gate + intermediate_size * hidden_size;     // size: intermediate_size * hidden_size
    float* shared_down = shared_up + intermediate_size * hidden_size;    // size: hidden_size * intermediate_size
    float* shared_intermediate = shared_down + hidden_size * intermediate_size;  // size: intermediate_size

    int tx = threadIdx.x;
    int bx = blockIdx.x;
    int blockDim = blockDim.x;

    // Map block to global token-expert pair index
    int global_idx = bx;

    // Decode to token_idx and expert_rank
    int token_idx = global_idx / top_k;
    int expert_rank = global_idx % top_k;

    // Bounds check
    if (token_idx >= num_tokens_original) return;

    // Get which expert to use and the weight for this execution
    int expert_idx = topk_idx_flat[global_idx];
    float weight = topk_weights[token_idx * top_k + expert_rank];

    // Compute weight sizes
    int weight_elems = intermediate_size * hidden_size;

    // Load gate and up weights for this expert cooperatively
    for (int i = tx; i < weight_elems; i += blockDim) {
        int linear_idx = expert_idx * weight_elems + i;
        shared_gate[i] = gate_weights[linear_idx];
        shared_up[i] = up_weights[linear_idx];
    }

    // Load down weights cooperatively  
    for (int i = tx; i < weight_elems; i += blockDim) {
        int linear_idx = expert_idx * weight_elems + i;
        shared_down[i] = down_weights[linear_idx];
    }

    __syncthreads();

    // Get pointer to the input token
    // expanded_tokens is (num_tokens * top_k, hidden_size)
    // Each token is repeated top_k times
    const float* input_ptr = expanded_tokens + global_idx * hidden_size;

    // Each thread computes one intermediate value
    int inter_elem = tx;
    if (inter_elem < intermediate_size) {
        // Compute gate projection: sum over hidden_size dimensions
        // shared_gate[inter_elem * hidden_size + j] * input_ptr[j]
        float gate_val = 0.0f;
        float up_val = 0.0f;

        #pragma unroll 4
        for (int j = 0; j < hidden_size; j++) {
            gate_val += shared_gate[inter_elem * hidden_size + j] * input_ptr[j];
            up_val += shared_up[inter_elem * hidden_size + j] * input_ptr[j];
        }

        // SiLU activation and element-wise multiply
        shared_intermediate[inter_elem] = silu(gate_val) * up_val;
    }

    __syncthreads();

    // Each thread computes one output element
    int out_elem = tx;
    if (out_elem < hidden_size) {
        float down_val = 0.0f;

        #pragma unroll 4
        for (int i = 0; i < intermediate_size; i++) {
            // down_weights[hidden_size * intermediate_size * expert_idx + out_elem * intermediate_size + i]
            down_val += shared_down[out_elem * intermediate_size + i] * shared_intermediate[i];
        }

        // Atomic add to accumulate contributions from all experts for this token
        int out_linear_idx = token_idx * hidden_size + out_elem;
        atomicAdd(&output[out_linear_idx], down_val * weight);
    }
}

torch::Tensor fused_expert_mlp_hip(
    torch::Tensor gate_weights,
    torch::Tensor up_weights,
    torch::Tensor down_weights,
    torch::Tensor expanded_tokens,
    torch::Tensor topk_idx_flat,
    torch::Tensor topk_weights,
    int num_tokens_original,
    int top_k
) {
    auto hidden_size = gate_weights.size(2);
    auto intermediate_size = gate_weights.size(1);
    auto n_experts = gate_weights.size(0);

    // Initialize output to zero (atomicAdd will accumulate)
    auto output = torch::zeros({num_tokens_original, hidden_size}, torch::kFloat32).cuda();

    int block_size = 256;
    int num_blocks = topk_idx_flat.size(0);  // num_tokens * top_k

    // Shared memory: gate + up + down + intermediate
    size_t gate_up_size = 2 * intermediate_size * hidden_size * sizeof(float);
    size_t down_size = hidden_size * intermediate_size * sizeof(float);
    size_t inter_size = intermediate_size * sizeof(float);
    size_t total_shared = gate_up_size + down_size + inter_size;

    fused_expert_mlp_kernel<<<num_blocks, block_size, total_shared>>>(
        gate_weights.data_ptr<float>(),
        up_weights.data_ptr<float>(),
        down_weights.data_ptr<float>(),
        expanded_tokens.data_ptr<float>(),
        topk_idx_flat.data_ptr<int32_t>(),
        topk_weights.data_ptr<float>(),
        output.data_ptr<float>(),
        num_tokens_original,
        top_k,
        hidden_size,
        intermediate_size,
        n_experts
    );

    hipError_t err = hipGetLastError();
    if (err != hipSuccess) {
        std::cerr << "HIP error: " << hipGetErrorString(err) << std::endl;
    }

    return output;
}
"""

fused_expert_mlp = load_inline(
    name="fused_expert_mlp",
    cpp_sources=fused_expert_cpp_source,
    functions=["fused_expert_mlp_hip"],
    verbose=True,
)


class MoEGate(nn.Module):
    def __init__(
        self,
        hidden_size: int,
        n_routed_experts: int,
        num_experts_per_tok: int,
        n_group: int,
        topk_group: int,
        routed_scaling_factor: float = 1.0,
        norm_topk_prob: bool = True,
    ):
        super().__init__()
        self.top_k = num_experts_per_tok
        self.n_routed_experts = n_routed_experts
        self.n_group = n_group
        self.topk_group = topk_group
        self.routed_scaling_factor = routed_scaling_factor
        self.norm_topk_prob = norm_topk_prob

        self.weight = nn.Parameter(torch.empty(n_routed_experts, hidden_size))
        self.register_buffer("e_score_correction_bias", torch.zeros(n_routed_experts))

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, hidden_states: torch.Tensor):
        bsz, seq_len, h = hidden_states.shape
        hidden_states = hidden_states.view(-1, h)

        logits = F.linear(hidden_states.float(), self.weight.float())
        scores = logits.sigmoid()
        scores_for_choice = scores + self.e_score_correction_bias.unsqueeze(0)

        group_scores = (
            scores_for_choice.view(bsz * seq_len, self.n_group, -1)
            .topk(2, dim=-1)[0]
            .sum(dim=-1)
        )
        group_idx = torch.topk(group_scores, k=self.topk_group, dim=-1, sorted=False)[1]
        group_mask = torch.zeros_like(group_scores)
        group_mask.scatter_(1, group_idx, 1)

        score_mask = (
            group_mask.unsqueeze(-1)
            .expand(bsz * seq_len, self.n_group, self.n_routed_experts // self.n_group)
            .reshape(bsz * seq_len, -1)
        )
        tmp_scores = scores_for_choice.masked_fill(~score_mask.bool(), 0.0)
        _, topk_idx = torch.topk(tmp_scores, k=self.top_k, dim=-1, sorted=False)

        topk_weight = scores.gather(1, topk_idx)

        if self.top_k > 1 and self.norm_topk_prob:
            denominator = topk_weight.sum(dim=-1, keepdim=True) + 1e-20
            topk_weight = topk_weight / denominator
        topk_weight = topk_weight * self.routed_scaling_factor

        return topk_idx, topk_weight


