    // Cooperative load of down weights
    for (size_t i = tx; i < weight_elems; i += blockDim.x) {
        size_t linear_idx = static_cast<size_t>(expert_idx) * weight_elems + i;
        shared_down[i] = down_weights[linear_idx];
    }

    __syncthreads();

